import "dart:convert";
import "package:flutter/material.dart";
import "package:flutter_secure_storage/flutter_secure_storage.dart";
import "package:http/http.dart" as http;
const baseUrl=String.fromEnvironment("FRAPPE_URL",defaultValue:"http://10.0.2.2:8000");
const secureStorage=FlutterSecureStorage();
void main()=>runApp(const WorkforceApp());
class WorkforceApp extends StatelessWidget{const WorkforceApp({super.key});@override Widget build(BuildContext context)=>MaterialApp(title:"Agency Workforce OS",theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xffc9fa68)),useMaterial3:true),home:const WorkspacePage());}
class WorkspacePage extends StatefulWidget{const WorkspacePage({super.key});@override State<WorkspacePage> createState()=>_WorkspacePageState();}
class _WorkspacePageState extends State<WorkspacePage>{Map<String,dynamic>? data;String? error;bool loading=true;final controller=TextEditingController();Future<void> load()async{setState((){loading=true;error=null;});try{final sid=await secureStorage.read(key:"sid");final r=await http.get(Uri.parse(baseUrl+"/api/method/agency_workforce_os.api.get_workspace"),headers:sid==null?{}:{"Cookie":"sid="+sid});if(r.statusCode!=200)throw Exception("Workspace request failed ("+r.statusCode.toString()+"). Sign in to Frappe.");data=Map<String,dynamic>.from((jsonDecode(r.body) as Map)["message"] as Map);}catch(e){error=e.toString();}if(mounted)setState(()=>loading=false);}Future<void> publish()async{try{final sid=await secureStorage.read(key:"sid");final r=await http.post(Uri.parse(baseUrl+"/api/method/agency_workforce_os.api.create_feed_post"),headers:{"Content-Type":"application/json",if(sid!=null)"Cookie":"sid="+sid},body:jsonEncode({"content":controller.text.trim(),"post_type":"General Update","visibility":"Team"}));if(r.statusCode!=200)throw Exception("Publish failed ("+r.statusCode.toString()+")");controller.clear();await load();}catch(e){setState(()=>error=e.toString());}}@override void initState(){super.initState();load();}@override void dispose(){controller.dispose();super.dispose();}@override Widget build(BuildContext context){final employee=data?["employee"] as Map<String,dynamic>?;final tasks=data?["tasks"] as List? ?? const [];final feed=data?["feed"] as List? ?? const [];return Scaffold(appBar:AppBar(title:const Text("Agency Workforce OS"),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Text(employee?["employee_name"]==null?"Your work, connected.":"Welcome, "+employee!["employee_name"].toString(),style:Theme.of(context).textTheme.headlineSmall),Text(employee?["department"]?.toString()??"Employee workspace"),const SizedBox(height:16),if(loading)const LinearProgressIndicator(),if(error!=null)Text(error!,style:TextStyle(color:Theme.of(context).colorScheme.error)),Row(children:[Expanded(child:_metric("My tasks",loading?"—":tasks.length.toString())),Expanded(child:_metric("Feed updates",loading?"—":feed.length.toString()))]),const SizedBox(height:18),const Text("Share a work update"),TextField(controller:controller,maxLines:3,maxLength:10000,decoration:const InputDecoration(border:OutlineInputBorder(),hintText:"Progress, blocker or request for help")),Align(alignment:Alignment.centerRight,child:FilledButton(onPressed:publish,child:const Text("Publish update"))),const SizedBox(height:16),Text("My tasks",style:Theme.of(context).textTheme.titleMedium),for(final t in tasks)ListTile(leading:const Icon(Icons.task_alt),title:Text(t["subject"]?.toString()??"Task"),subtitle:Text(t["status"]?.toString()??"Status unavailable")),const SizedBox(height:16),Text("Workplace feed",style:Theme.of(context).textTheme.titleMedium),for(final p in feed)Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person)),title:Text(p["owner"]?.toString()??"Employee"),subtitle:Text(p["content"]?.toString()??"")))])),bottomNavigationBar:NavigationBar(selectedIndex:0,destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:"Home"),NavigationDestination(icon:Icon(Icons.dynamic_feed_outlined),label:"Feed"),NavigationDestination(icon:Icon(Icons.task_alt),label:"Tasks"),NavigationDestination(icon:Icon(Icons.person_outline),label:"Profile")]));}Widget _metric(String label,String value)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label),const SizedBox(height:8),Text(value,style:const TextStyle(fontSize:26,fontWeight:FontWeight.bold))])));}
